head.script:
// https://inswave01.atlassian.net/browse/WAEA-1370
// https://inswave01.atlassian.net/browse/WAEA-1376



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > invalidMessageFunc]<br/>inputType='calendar' 인 Column 에서 입력값의 유효성 검증이 실패했을때 처리하기 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "Column 의 dateValidSet=true, dateValidSetCustom=true 이면 사용자 함수에서 입력값을 원복하는 처리를 구현할 수 있습니다.",
        "invalidMessageFunc 속성은 사용자가 Column 에 값을 직접 입력한 경우에 적용되며, 스크립트나 서버 응답으로 DataList 에 값이 설정된 경우엔 적용되지 않습니다.",
    ]
}

// 사용자 정의 함수의 원복 처리 방식 (Target 재생성 시 con_restore 값으로 확정)
scwin.cRestore = "";



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (원복 처리 구현)
    con_restore.setValue("setValueCancel");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - cal : 검증 대상 Body Column (inputType="calendar" + dataType="date", dateValidSet="true", dateValidSetCustom="true",
//          invalidMessageFunc="scwin.target1_cal_invalidMessageFunc" 고정)
//  - con_restore : 사용자 정의 함수에서 원복 처리(setValueCancel) 구현 여부
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] cal Column 은 dateValidSet=true, dateValidSetCustom=true 고정\n[절차] 결과창 clear -> cal 셀 클릭 -> 유효하지 않은 날짜(예: 20261345) 입력 -> 셀 밖(원복 처리 라벨) 클릭 -> 셀 값 확인\n[확인] 원복 처리 setValueCancel 이면 입력창이 이전 값으로 복원 (셀 밖을 한 번 더 클릭하면 편집 종료), 빈값이면 입력값 유지\nsetCellData / setJSON 클릭 시 호출 줄 없이 Row 값만 출력 (확인 후 Target 재생성)"', '', 'label1');

    // 원복 처리 방식 확정
    scwin.cRestore = con_restore.getValue();

    // dataList 생성 (calendar Column 바인딩 컬럼은 dataType="date")
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cal" name="cal" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "cal" : "20261001" },
        { "cal" : "20261015" }
    ], false);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:300px;height:120px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="260" style="" inputType="text" id="column1" value="cal"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="260" style="" id="cal" inputType="calendar" dataType="date" viewType="icon" calendarValueType="yearMonthDate"'
        + ' dateValidSet="true" dateValidSetCustom="true" invalidMessageFunc="scwin.target1_cal_invalidMessageFunc"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1 : 사용자 정의 함수에서 편집 중인 inputCalendar 를 얻어 원복 처리 (setValueCancel)
// validation 2 : 직접 입력 시 호출 줄 출력
scwin.target1_cal_invalidMessageFunc = function () {
    let inputCalendar = this.getCaller();
    let inputValue = inputCalendar.getValue();
    if (scwin.cRestore === "setValueCancel") {
        inputCalendar.setValueCancel();
        wf_body_bottom.getObj("scwin").setReturnValue("invalidMessageFunc 호출 : " + inputValue + " -> " + inputCalendar.getValue());
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("invalidMessageFunc 호출 : " + inputValue);
    }
}



// validation 2 : 스크립트로 DataList 에 무효 날짜 설정 (사용자 정의 함수 미호출)
scwin.btn_setCellData_onclick = function (e) {
    dlt_bind.setCellData(1, "cal", "20261345");
    wf_body_bottom.getObj("scwin").setReturnValue("Row 1 '" + dlt_bind.getCellData(1, "cal") + "'");
}



// validation 2 : 서버 응답과 같이 DataList 전체에 무효 날짜 설정 (사용자 정의 함수 미호출)
scwin.btn_setJSON_onclick = function (e) {
    dlt_bind.setJSON([
        { "cal" : "20261345" },
        { "cal" : "20269999" }
    ], false);
    scwin.btn_getCellData_onclick();
}



// validation 1, 2 : DataList 전체 Row 값
scwin.btn_getCellData_onclick = function (e) {
    let rowCnt = dlt_bind.getRowCount();
    for (let i = 0; i < rowCnt; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("Row " + i + " '" + dlt_bind.getCellData(i, "cal") + "'");
    }
}
